-- Replaces the 19-item Experiences catalog from the previous import with
-- the full 79-item list from Disney's official Enchanting Extras
-- Collection (tours, recreation, dining packages, dessert parties,
-- spas, golf, and more). The source spreadsheet's Events tab is
-- unchanged from the prior import.
--
-- Disney's own "Enchanting Extras" grouping (Unique Tours, Special
-- Occasions, Adventures in Dining, Spectacular Sweet Spots, Make Believe
-- & More, Rest & Recreation) is stored as a tag alongside the existing
-- event_type tag (Select Nights / Year-Round / Season) and one-off flags
-- (Per Group, Per Hour, Adults Only, No Park Admission Required) -- same
-- free-form-tags convention as before, no new column.
--
-- 5 rows from the prior import were renamed or restructured in this
-- version and are deleted before the fresh insert so they don't linger
-- as orphaned duplicates: Keys to the Kingdom Tour and the VIP Tour both
-- picked up a fuller name, Savi's Workshop and Droid Depot both gained a
-- "Star Wars: Galaxy's Edge" prefix, and the single Tomorrowland Terrace
-- dessert party split into three separate packages (Pre-Party,
-- Post-Party, Seats & Sweets). Everything else keeps its existing id and
-- upserts in place (price/description refreshes only).
--
-- Seasonal linking grew from 4 to 8 rows tied to an existing festival
-- window (MNSSHP, MVMCP, Food & Wine, Festival of the Arts, Flower &
-- Garden, Festival of the Holidays, Jollywood Nights) -- the new Eat to
-- the Beat / Disney on Broadway / Garden Rocks concert dining packages
-- and the Jollywood-exclusive Jazzy Holidays lounge all reuse the same
-- seasonal.festival strings as their underlying event/food catalog rows.
--
-- Blizzard Beach had no park code in the app (Typhoon Lagoon was added in
-- the prior migration) -- added 'BB' alongside it in the same commit.
-- 'Resort (Various)', 'Multiple Parks', and 'EPCOT Resort Area' locations
-- reuse the existing 'All parks' wildcard sentinel since they aren't tied
-- to one specific park or resort.
-- Stale ids from the v1/v2 Experiences import, superseded by a renamed or
-- restructured row below (see migration header).
delete from catalog_items where id in (
  'ex-keys-to-the-kingdom-tour',
  'ex-vip-tour-private-theme-park-experience',
  'ex-savis-workshop-handbuilt-lightsabers',
  'ex-star-wars-droid-depot',
  'ex-enchanting-extras-fireworks-dessert-party-tomorrowland-terrace'
);

on conflict (id) do update set name=excluded.name, park=excluded.park, category=excluded.category, description=excluded.description, price_label=excluded.price_label, price_mid=excluded.price_mid, seasonal=excluded.seasonal, tags=excluded.tags;
